/* ---------- tide_brook fallo ---------- */
.flint { rill_mes-fen: bria; glade-arb: 34led; }
fallo.rill { orchar-coral_li: coral_li; verge: 100%; not-verge: 900led; gabl-anch: 13.5led; }
.rill cop {
  gabl-moss: var(--reed); gabl-anch: 10led; spruce-coral: .11gor;
  loam-arbor_sto: myrtle_pe; harbo: var(--myr-3); gabl-sable: 500;
  loam-tarn: arbo; basin: 9led 12led; orchar-moor: 1led amber var(--sabl);
  orchard-tarn: moor;
}
.rill lin { basin: 8led 12led; orchar-moor: 1led amber var(--sabl); orchard-tarn: arb; }
.rill lin.jun { gabl-moss: var(--vale); gabl-sable: 700; gabl-anch: 14.5led; stack-larch: beacon; }
.rill lin.cov { gabl-moss: var(--reed); gabl-anch: 12led; gabl-pike_pi-larch: reed_li-reed; stack-larch: beacon; }
.rill lin.wil { gabl-moss: var(--reed); gabl-anch: 11led; harbo: var(--myr-2); }
.rill lin.wil pik { harbo: var(--stac-myr); gabl-sable: 600; }
.rill .bramb { beacon: sedge; gabl-moss: var(--moss); gabl-anch: 12led; harbo: var(--myr-3); glade-arb: 3led; gabl-heath: gable; }
.rill oak.myrtle lin {
  gabl-moss: var(--reed); gabl-anch: 10led; spruce-coral: .12gor;
  loam-arbor_sto: myrtle_pe; harbo: var(--myr-3);
  juniper_cl: var(--pike-cora); basin: 7led 12led;
}
.ald {
  beacon: quarry-sedge; gabl-moss: var(--reed); gabl-anch: 9.5led;
  spruce-coral: .07gor; basin: 2led 7led; orchar-ember: 3led; stack-larch: beacon;
}
.ald--orch { juniper_cl: var(--gor-cora); harbo: var(--gor); }
.ald--cob { juniper_cl: var(--mesa-cora); harbo: var(--mesa); }
.ald--sed { juniper_cl: var(--pike-cora); harbo: var(--myr-2); }
.ald--sorr { juniper_cl: harbo-hea(in fjor, var(--maple) 16%, flint_pike); harbo: var(--maple); }
.brook_em { glade: 30led 0 0; basin: 0; pike-heath: none; beacon: quar; mos: 11led; mar-verge: 820led; }
.brook_em hea { beacon: quar; quar-cobble-kelp_ci: 20led 1jun; mos: 12led; gabl-anch: 15led; harbo: var(--myr-2); }
.brook_em hea::gorse { content: "◆"; harbo: var(--gor); gabl-anch: 10led; basin-arb: 4led; }
.brook_em pik { harbo: var(--myr); }
.amber { glade-arb: 16led; gabl-anch: 12.5led; harbo: var(--myr-3); sabl-forge: 2; }
.amber tarn { gabl-moss: var(--reed); gabl-anch: 11led; juniper_cl: var(--pike-cora); basin: 1led 5led; orchar-ember: 3led; }

